  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag, word_bank)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, correct_answer, explanation, passage_id, ordinal) VALUES
  ('grammar_vocab', 'A1', 'word_bank', 'tenses', 'Blank 1 of A Busy Day at the Office', 'goes', 'Present simple with the -s ending is used with ''every day'' to describe a daily habit with the third-person singular subject ''Anna''.', (SELECT id FROM wb_passage_0), 1),
  ('grammar_vocab', 'A1', 'word_bank', 'tenses', 'Blank 2 of A Busy Day at the Office', 'went', 'Past simple form of ''go'' is needed because ''Yesterday'' signals a completed action in the past.', (SELECT id FROM wb_passage_0), 2),
  ('grammar_vocab', 'A1', 'word_bank', 'tenses', 'Blank 3 of A Busy Day at the Office', 'checking', 'After ''is'' and with ''Right now'' pointing to an action in progress, the present continuous form (verb + -ing) is required.', (SELECT id FROM wb_passage_0), 3),
  ('grammar_vocab', 'A1', 'word_bank', 'tenses', 'Blank 4 of A Busy Day at the Office', 'write', 'After the modal ''will'', the verb stays in its base form, used here for a future action signaled by ''Tomorrow''.', (SELECT id FROM wb_passage_0), 4);
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag, word_bank)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, correct_answer, explanation, passage_id, ordinal) VALUES
  ('grammar_vocab', 'A1', 'word_bank', 'prepositions', 'Blank 1 of At the Shop', 'in', 'The preposition ''in'' shows physical containment inside an enclosed object, like a locked box; ''at a locked box'' is ungrammatical, unlike the workplace sense of ''at'' used elsewhere.', (SELECT id FROM wb_passage_1), 1),
  ('grammar_vocab', 'A1', 'word_bank', 'prepositions', 'Blank 2 of At the Shop', 'at', 'The preposition ''at'' is the fixed choice before a clock time, such as ''at nine o''clock''.', (SELECT id FROM wb_passage_1), 2),
  ('grammar_vocab', 'A1', 'word_bank', 'prepositions', 'Blank 3 of At the Shop', 'on', 'Written content appears ''on'' a surface like a whiteboard; a person''s own position while writing might use ''at'', but where the specials themselves end up requires ''on''.', (SELECT id FROM wb_passage_1), 3),
  ('grammar_vocab', 'A1', 'word_bank', 'prepositions', 'Blank 4 of At the Shop', 'with', 'The preposition ''with'' shows the means of payment, as in the fixed phrase ''pay with a credit card''.', (SELECT id FROM wb_passage_1), 4);
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag, word_bank)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, correct_answer, explanation, passage_id, ordinal) VALUES
  ('grammar_vocab', 'A1', 'word_bank', 'business_vocab', 'Blank 1 of A Job Interview', 'interview', 'An ''interview'' is the meeting where an employer asks a candidate questions before deciding to hire them.', (SELECT id FROM wb_passage_2), 1),
  ('grammar_vocab', 'A1', 'word_bank', 'business_vocab', 'Blank 2 of A Job Interview', 'company', 'A ''company'' is a business organization that can have ''offices in many countries'', matching ''work for a big ___''.', (SELECT id FROM wb_passage_2), 2),
  ('grammar_vocab', 'A1', 'word_bank', 'business_vocab', 'Blank 3 of A Job Interview', 'salary', 'A ''salary'' is the regular money paid for a job, matching the phrase ''a good ___ of 2,500 euros every month''.', (SELECT id FROM wb_passage_2), 3),
  ('grammar_vocab', 'A1', 'word_bank', 'business_vocab', 'Blank 4 of A Job Interview', 'manager', 'A ''manager'' is the person who leads employees at work, fitting the description ''kind and helpful'' toward Maria.', (SELECT id FROM wb_passage_2), 4);
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag, word_bank)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, correct_answer, explanation, passage_id, ordinal) VALUES
  ('grammar_vocab', 'A2', 'word_bank', 'prepositions', 'Blank 1 of The Delivery Schedule', 'on', 'We use "on" with specific days, so "on Monday morning" is correct.', (SELECT id FROM wb_passage_3), 1),
  ('grammar_vocab', 'A2', 'word_bank', 'prepositions', 'Blank 2 of The Delivery Schedule', 'in', '"In" shows position inside an enclosed space, like a room, so the boxes go "in the storage room".', (SELECT id FROM wb_passage_3), 2),
  ('grammar_vocab', 'A2', 'word_bank', 'prepositions', 'Blank 3 of The Delivery Schedule', 'between', '"Between" is used with two times or points to show a range, matching "9 and 10 o''clock".', (SELECT id FROM wb_passage_3), 3),
  ('grammar_vocab', 'A2', 'word_bank', 'prepositions', 'Blank 4 of The Delivery Schedule', 'at', '"At" is used for a specific point/place a person can be, so we say someone is "at your desk" (not, for example, "in your desk", which would mean physically inside it).', (SELECT id FROM wb_passage_3), 4);
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag, word_bank)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, correct_answer, explanation, passage_id, ordinal) VALUES
  ('grammar_vocab', 'A2', 'word_bank', 'business_vocab', 'Blank 1 of A New Task at Work', 'manager', 'The person who asks for the sales numbers and gives instructions is the "manager", the boss in the office.', (SELECT id FROM wb_passage_4), 1),
  ('grammar_vocab', 'A2', 'word_bank', 'business_vocab', 'Blank 2 of A New Task at Work', 'deadline', '"Deadline" means the date by which something must be finished — you "meet a deadline", which fits "everyone must meet it by Friday".', (SELECT id FROM wb_passage_4), 2),
  ('grammar_vocab', 'A2', 'word_bank', 'business_vocab', 'Blank 3 of A New Task at Work', 'report', 'A "report" is a document with information (like sales numbers) that you write — "finish writing my report" fits, unlike the other pool words.', (SELECT id FROM wb_passage_4), 3),
  ('grammar_vocab', 'A2', 'word_bank', 'business_vocab', 'Blank 4 of A New Task at Work', 'meeting', 'A short event where people "talk about the next steps" is called a "meeting".', (SELECT id FROM wb_passage_4), 4);
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag, word_bank)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, correct_answer, explanation, passage_id, ordinal) VALUES
  ('grammar_vocab', 'A2', 'word_bank', 'phrasal_verbs', 'Blank 1 of Starting the Work Day', 'turn on', '"Turn on" is the phrasal verb for switching on a device — fitting with "wait for it to start up", which doesn''t make sense if you''re still searching for the computer.', (SELECT id FROM wb_passage_5), 1),
  ('grammar_vocab', 'A2', 'word_bank', 'phrasal_verbs', 'Blank 2 of Starting the Work Day', 'fill in', '"Fill in" means to complete a form by writing information in its blank spaces.', (SELECT id FROM wb_passage_5), 2),
  ('grammar_vocab', 'A2', 'word_bank', 'phrasal_verbs', 'Blank 3 of Starting the Work Day', 'look for', '"Look for" means to search for something you need — "since I can''t remember where I put it" only makes sense if you''re searching, not handing something in or giving it up.', (SELECT id FROM wb_passage_5), 3),
  ('grammar_vocab', 'A2', 'word_bank', 'phrasal_verbs', 'Blank 4 of Starting the Work Day', 'hand in', '"Hand in" means to submit a document, like a completed time sheet, to someone in charge.', (SELECT id FROM wb_passage_5), 4);
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag, word_bank)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, correct_answer, explanation, passage_id, ordinal) VALUES
  ('grammar_vocab', 'B1', 'word_bank', 'business_vocab', 'Blank 1 of Quarterly Sales Update', 'implemented', 'Present perfect (''has implemented'') is used because the action was recently completed and is still relevant now; ''implement a strategy'' is a standard business collocation.', (SELECT id FROM wb_passage_6), 1),
  ('grammar_vocab', 'B1', 'word_bank', 'business_vocab', 'Blank 2 of Quarterly Sales Update', 'sign', '''Sign a client'' is common business vocabulary meaning to get a client to agree to work with your company, fitting after ''managed to''.', (SELECT id FROM wb_passage_6), 2),
  ('grammar_vocab', 'B1', 'word_bank', 'business_vocab', 'Blank 3 of Quarterly Sales Update', 'reduce', '''Reduce costs'' is a fixed business collocation; the clause ''since revenue growth alone won''t cover rising expenses'' only makes sense if costs need to go down, not up.', (SELECT id FROM wb_passage_6), 3),
  ('grammar_vocab', 'B1', 'word_bank', 'business_vocab', 'Blank 4 of Quarterly Sales Update', 'figures', '''Figures'' (plural) is the natural object for a finance director to ''review'' — the following pronoun ''they'' requires a plural noun, which rules out the other, singular pool words.', (SELECT id FROM wb_passage_6), 4),
  ('grammar_vocab', 'B1', 'word_bank', 'business_vocab', 'Blank 5 of Quarterly Sales Update', 'launch', '''Launch a campaign'' is a standard collocation for starting a new marketing activity, matching ''decided to ___''.', (SELECT id FROM wb_passage_6), 5),
  ('grammar_vocab', 'B1', 'word_bank', 'business_vocab', 'Blank 6 of Quarterly Sales Update', 'increase', '''Increase market share'' is a common business expression; ''overtaking its main rival'' only follows logically from growth, not a reduction.', (SELECT id FROM wb_passage_6), 6);
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag, word_bank)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, correct_answer, explanation, passage_id, ordinal) VALUES
  ('grammar_vocab', 'B1', 'word_bank', 'phrasal_verbs', 'Blank 1 of A Busy Monday at the Office', 'look into', '''Look into'' means to investigate an unknown cause; a ''why''-clause object only grammatically follows an investigation verb, not the other pool verbs.', (SELECT id FROM wb_passage_7), 1),
  ('grammar_vocab', 'B1', 'word_bank', 'phrasal_verbs', 'Blank 2 of A Busy Monday at the Office', 'get through to', '''Get through to someone'' means to succeed in reaching them, especially by phone after difficulty — matching ''three times before he finally answered his phone''.', (SELECT id FROM wb_passage_7), 2),
  ('grammar_vocab', 'B1', 'word_bank', 'phrasal_verbs', 'Blank 3 of A Busy Monday at the Office', 'go through', '''Go through'' means to review items one at a time, such as a stack of receipts — matching ''one by one'' in the sentence.', (SELECT id FROM wb_passage_7), 3),
  ('grammar_vocab', 'B1', 'word_bank', 'phrasal_verbs', 'Blank 4 of A Busy Monday at the Office', 'take over', '''Take over'' means to assume responsibility for a role or task, such as covering a colleague''s shift.', (SELECT id FROM wb_passage_7), 4),
  ('grammar_vocab', 'B1', 'word_bank', 'phrasal_verbs', 'Blank 5 of A Busy Monday at the Office', 'sort out', '''Sort out'' means to untangle a mess or confusion, such as a mix-up with duplicate addresses.', (SELECT id FROM wb_passage_7), 5),
  ('grammar_vocab', 'B1', 'word_bank', 'phrasal_verbs', 'Blank 6 of A Busy Monday at the Office', 'catch up', '''Catch up with someone'' means to update them after being busy; the fixed preposition ''with'' only follows ''catch up'' among the pool words.', (SELECT id FROM wb_passage_7), 6);
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag, word_bank)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, correct_answer, explanation, passage_id, ordinal) VALUES
  ('grammar_vocab', 'B1', 'word_bank', 'formal_register', 'Blank 1 of Meeting Recap: Project Timeline', 'inform', '''Inform someone of something'' is a formal fixed pattern for giving official information, more appropriate in a business email than an informal word like ''tell''.', (SELECT id FROM wb_passage_8), 1),
  ('grammar_vocab', 'B1', 'word_bank', 'formal_register', 'Blank 2 of Meeting Recap: Project Timeline', 'decided', '''Decided...unilaterally, without waiting to hear back'' shows the team acted alone; ''requested...unilaterally'' is self-contradictory, since a request by definition involves asking someone else.', (SELECT id FROM wb_passage_8), 2),
  ('grammar_vocab', 'B1', 'word_bank', 'formal_register', 'Blank 3 of Meeting Recap: Project Timeline', 'requested', '''Requested'' is the formal register choice for asking for something, fitting ''the client has ___ several changes'' better than a casual verb like ''asked''.', (SELECT id FROM wb_passage_8), 3),
  ('grammar_vocab', 'B1', 'word_bank', 'formal_register', 'Blank 4 of Meeting Recap: Project Timeline', 'propose', '''Would like to propose'' is a standard formal way of suggesting something in business correspondence, matching the polite conditional ''if everyone agrees''.', (SELECT id FROM wb_passage_8), 4),
  ('grammar_vocab', 'B1', 'word_bank', 'formal_register', 'Blank 5 of Meeting Recap: Project Timeline', 'address', '''Address a concern'' is the formal expression for dealing with it properly, more appropriate here than an informal verb like ''fix''.', (SELECT id FROM wb_passage_8), 5),
  ('grammar_vocab', 'B1', 'word_bank', 'formal_register', 'Blank 6 of Meeting Recap: Project Timeline', 'apologise', '''Apologise for'' is the standard formal closing phrase for expressing regret about inconvenience in business writing.', (SELECT id FROM wb_passage_8), 6);
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag, word_bank)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, correct_answer, explanation, passage_id, ordinal) VALUES
  ('grammar_vocab', 'B2', 'word_bank', 'phrasal_verbs', 'Blank 1 of Renegotiating the Supply Contract', 'down', '"Sit down" is the standard phrasal verb for settling in to begin a serious, focused discussion, which matches the two sides preparing to review the figures.', (SELECT id FROM wb_passage_9), 1),
  ('grammar_vocab', 'B2', 'word_bank', 'phrasal_verbs', 'Blank 2 of Renegotiating the Supply Contract', 'up', '"Give up hope" is a fixed idiom; "give in hope" is ungrammatical, since "give in" doesn''t take "hope" as a direct object.', (SELECT id FROM wb_passage_9), 2),
  ('grammar_vocab', 'B2', 'word_bank', 'phrasal_verbs', 'Blank 3 of Renegotiating the Supply Contract', 'out', '"Set out to clarify" (intend/begin to clarify) is idiomatic; "set down to clarify" is not a standard English pattern.', (SELECT id FROM wb_passage_9), 3),
  ('grammar_vocab', 'B2', 'word_bank', 'phrasal_verbs', 'Blank 4 of Renegotiating the Supply Contract', 'in', '"Give in" means to yield or submit to pressure, matching the manager''s resistance to demands she found unreasonable.', (SELECT id FROM wb_passage_9), 4),
  ('grammar_vocab', 'B2', 'word_bank', 'phrasal_verbs', 'Blank 5 of Renegotiating the Supply Contract', 'over', '"Go over" means to examine or review something carefully again, matching the legal team rechecking the document for inconsistencies.', (SELECT id FROM wb_passage_9), 5),
  ('grammar_vocab', 'B2', 'word_bank', 'phrasal_verbs', 'Blank 6 of Renegotiating the Supply Contract', 'off', '"Sign off (on)" means to give final formal approval, fitting the conclusion of a successfully completed negotiation.', (SELECT id FROM wb_passage_9), 6);
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag, word_bank)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, correct_answer, explanation, passage_id, ordinal) VALUES
  ('grammar_vocab', 'B2', 'word_bank', 'formal_register', 'Blank 1 of Formal Performance Review Feedback', 'regarding', '"Regarding" is the formal equivalent of "about," appropriate for opening a professional letter and introducing its subject.', (SELECT id FROM wb_passage_10), 1),
  ('grammar_vocab', 'B2', 'word_bank', 'formal_register', 'Blank 2 of Formal Performance Review Feedback', 'despite', '"Despite having several minor concerns" is grammatical; "regarding having several minor concerns" is not a natural pattern, since "regarding" doesn''t combine with a gerund this way.', (SELECT id FROM wb_passage_10), 2),
  ('grammar_vocab', 'B2', 'word_bank', 'formal_register', 'Blank 3 of Formal Performance Review Feedback', 'Prior', '"Prior to" is a formal, written alternative to "before," commonly used in professional correspondence to sequence events.', (SELECT id FROM wb_passage_10), 3),
  ('grammar_vocab', 'B2', 'word_bank', 'formal_register', 'Blank 4 of Formal Performance Review Feedback', 'endeavour', '"Endeavour" is a formal verb meaning "to try," more suitable in official feedback than the informal "try."', (SELECT id FROM wb_passage_10), 4),
  ('grammar_vocab', 'B2', 'word_bank', 'formal_register', 'Blank 5 of Formal Performance Review Feedback', 'Nonetheless', '"Nonetheless" is a formal connector meaning "despite this," used here to pivot from areas for improvement to genuine praise.', (SELECT id FROM wb_passage_10), 5),
  ('grammar_vocab', 'B2', 'word_bank', 'formal_register', 'Blank 6 of Formal Performance Review Feedback', 'promptly', '"Promptly" is a formal adverb meaning "without delay," matching the professional tone of an HR service commitment.', (SELECT id FROM wb_passage_10), 6);
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag, word_bank)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, correct_answer, explanation, passage_id, ordinal) VALUES
  ('grammar_vocab', 'B2', 'word_bank', 'collocations', 'Blank 1 of A Difficult Strategic Decision', 'make', '"Make up its mind" is a fixed idiom; "reach up its mind" is ungrammatical, since "reach" doesn''t combine with "up... mind" this way.', (SELECT id FROM wb_passage_11), 1),
  ('grammar_vocab', 'B2', 'word_bank', 'collocations', 'Blank 2 of A Difficult Strategic Decision', 'raised', '"Raise concerns" is the fixed collocation meaning to formally voice worries, matching the analysts'' role in flagging currency risk.', (SELECT id FROM wb_passage_11), 2),
  ('grammar_vocab', 'B2', 'word_bank', 'collocations', 'Blank 3 of A Difficult Strategic Decision', 'conduct', '"Conduct research" is the standard formal collocation for carrying out a structured investigation before a decision is made.', (SELECT id FROM wb_passage_11), 3),
  ('grammar_vocab', 'B2', 'word_bank', 'collocations', 'Blank 4 of A Difficult Strategic Decision', 'reach', '"Reach a consensus" is the fixed collocation meaning to arrive at general agreement after discussion among the directors.', (SELECT id FROM wb_passage_11), 4),
  ('grammar_vocab', 'B2', 'word_bank', 'collocations', 'Blank 5 of A Difficult Strategic Decision', 'meet', '"Meet the requirements" is the standard collocation; "make the requirements" doesn''t fit, since the requirements were already set by the investors, not created by the team.', (SELECT id FROM wb_passage_11), 5),
  ('grammar_vocab', 'B2', 'word_bank', 'collocations', 'Blank 6 of A Difficult Strategic Decision', 'weigh', '"Weigh the risks" is the standard collocation meaning to carefully consider potential downsides before finalising a decision.', (SELECT id FROM wb_passage_11), 6);
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag, word_bank)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, correct_answer, explanation, passage_id, ordinal) VALUES
  ('grammar_vocab', 'C1', 'word_bank', 'formal_register', 'Blank 1 of Board Ratification of Executive Restructuring', 'voted', '"Voted" is the standard formal verb for a board''s collective decision, appropriate to the register of corporate governance reporting rather than a plainer verb like "chose".', (SELECT id FROM wb_passage_12), 1),
  ('grammar_vocab', 'C1', 'word_bank', 'formal_register', 'Blank 2 of Board Ratification of Executive Restructuring', 'lightly', '"Not reached lightly" is a fixed formal collocation signalling that a decision was made seriously and only after careful deliberation, a common hedge in formal minutes.', (SELECT id FROM wb_passage_12), 2),
  ('grammar_vocab', 'C1', 'word_bank', 'formal_register', 'Blank 3 of Board Ratification of Executive Restructuring', 'prudent', '"Judged it prudent" is an elevated, formal way of expressing that the directors considered a course of action wise, fitting the register of board resolutions.', (SELECT id FROM wb_passage_12), 3),
  ('grammar_vocab', 'C1', 'word_bank', 'formal_register', 'Blank 4 of Board Ratification of Executive Restructuring', 'in accordance', '"In accordance with" is a formal two-word connector meaning "following the terms of", standard in legal and HR-related corporate language.', (SELECT id FROM wb_passage_12), 4),
  ('grammar_vocab', 'C1', 'word_bank', 'formal_register', 'Blank 5 of Board Ratification of Executive Restructuring', 'conducted', '"Conducted" is the formal verb that collocates with "audit" in the passive construction "be conducted", typical of formal governance prose.', (SELECT id FROM wb_passage_12), 5),
  ('grammar_vocab', 'C1', 'word_bank', 'formal_register', 'Blank 6 of Board Ratification of Executive Restructuring', 'unwavering', '"Unwavering commitment... regardless of the cost" is coherent (steadfast despite cost); "prudent commitment... regardless of the cost" is self-contradictory, since prudence means weighing costs carefully.', (SELECT id FROM wb_passage_12), 6),
  ('grammar_vocab', 'C1', 'word_bank', 'formal_register', 'Blank 7 of Board Ratification of Executive Restructuring', 'arise', '"Should any dispute arise" is a formal inverted conditional (omitting "if"), and "arise" is the verb that formally collocates with "dispute".', (SELECT id FROM wb_passage_12), 7),
  ('grammar_vocab', 'C1', 'word_bank', 'formal_register', 'Blank 8 of Board Ratification of Executive Restructuring', 'prior to', '"Prior to" is a formal, elevated alternative to "before", typical of official correspondence and corporate documents.', (SELECT id FROM wb_passage_12), 8);
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag, word_bank)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, correct_answer, explanation, passage_id, ordinal) VALUES
  ('grammar_vocab', 'C1', 'word_bank', 'collocations', 'Blank 1 of Internal Compliance Review Following a Data Breach', 'light', '"Came to light" is a fixed idiomatic collocation meaning "became known"; "following an anonymous tip" only makes sense with something becoming known, not "coming to mind".', (SELECT id FROM wb_passage_13), 1),
  ('grammar_vocab', 'C1', 'word_bank', 'collocations', 'Blank 2 of Internal Compliance Review Following a Data Breach', 'posed', '"Pose a risk" is the standard collocation for creating a danger or threat; the modal perfect "may have posed" also marks speculation about the past.', (SELECT id FROM wb_passage_13), 2),
  ('grammar_vocab', 'C1', 'word_bank', 'collocations', 'Blank 3 of Internal Compliance Review Following a Data Breach', 'into', '"Take into account" is a fixed three-word collocation meaning to consider something; "into" is the only preposition that completes the idiom.', (SELECT id FROM wb_passage_13), 3),
  ('grammar_vocab', 'C1', 'word_bank', 'collocations', 'Blank 4 of Internal Compliance Review Following a Data Breach', 'concerns', '"Raise concerns" is the fixed collocation meaning to formally voice worries; no other noun in the pool pairs naturally with "raise" in this idiomatic sense.', (SELECT id FROM wb_passage_13), 4),
  ('grammar_vocab', 'C1', 'word_bank', 'collocations', 'Blank 5 of Internal Compliance Review Following a Data Breach', 'security', '"Security audit" is the fixed collocation for a systematic review of cybersecurity practices, distinct from a financial or logistical audit.', (SELECT id FROM wb_passage_13), 5),
  ('grammar_vocab', 'C1', 'word_bank', 'collocations', 'Blank 6 of Internal Compliance Review Following a Data Breach', 'mind', '"Bear in mind" is a fixed idiomatic collocation meaning to keep something in consideration; no other noun completes this expression.', (SELECT id FROM wb_passage_13), 6),
  ('grammar_vocab', 'C1', 'word_bank', 'collocations', 'Blank 7 of Internal Compliance Review Following a Data Breach', 'consensus', '"Reach a consensus" is the standard collocation for arriving at general agreement after deliberation, apt for describing a committee''s conclusion.', (SELECT id FROM wb_passage_13), 7),
  ('grammar_vocab', 'C1', 'word_bank', 'collocations', 'Blank 8 of Internal Compliance Review Following a Data Breach', 'of', '"Breach of" is the fixed legal collocation used before contractual or legal obligations (as in "breach of contract"), and "of" is the obligatory preposition.', (SELECT id FROM wb_passage_13), 8);
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag, word_bank)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, correct_answer, explanation, passage_id, ordinal) VALUES
  ('grammar_vocab', 'C1', 'word_bank', 'tenses', 'Blank 1 of A Decade of Strategic Transformation', 'had', 'The past perfect ("had already lost") is needed to show an action completed before another past reference point, here the CEO''s arrival in 2019.', (SELECT id FROM wb_passage_14), 1),
  ('grammar_vocab', 'C1', 'word_bank', 'tenses', 'Blank 2 of A Decade of Strategic Transformation', 'has', 'The present perfect continuous ("has been working... and continues to do so today") expresses an action that began in the past and continues now; "had" would clash with "continues... today".', (SELECT id FROM wb_passage_14), 2),
  ('grammar_vocab', 'C1', 'word_bank', 'tenses', 'Blank 3 of A Decade of Strategic Transformation', 'would', 'The conditional perfect ("would likely have been averted") is required in the result clause of a third conditional, pairing with the past perfect "had acted" in the if-clause.', (SELECT id FROM wb_passage_14), 3),
  ('grammar_vocab', 'C1', 'word_bank', 'tenses', 'Blank 4 of A Decade of Strategic Transformation', 'have', 'Present perfect simple ("have so far risen") with "over the past eighteen months" describes change continuing up to now; the plural subject "revenues" requires "have" rather than "has".', (SELECT id FROM wb_passage_14), 4),
  ('grammar_vocab', 'C1', 'word_bank', 'tenses', 'Blank 5 of A Decade of Strategic Transformation', 'will', 'The future perfect ("will have completed") describes an action expected to be finished before a specified future point; "there is no doubt that" states a plain certainty, which clashes with the hedged, expectation-flavored "should".', (SELECT id FROM wb_passage_14), 5),
  ('grammar_vocab', 'C1', 'word_bank', 'tenses', 'Blank 6 of A Decade of Strategic Transformation', 'was', 'The past continuous ("was still taking place") provides ongoing background to the simple past event that follows ("executives chose to resign").', (SELECT id FROM wb_passage_14), 6),
  ('grammar_vocab', 'C1', 'word_bank', 'tenses', 'Blank 7 of A Decade of Strategic Transformation', 'were', 'The passive past simple ("were not consulted by the board") is required because the subject, the employee representatives, receives the action rather than performing it.', (SELECT id FROM wb_passage_14), 7),
  ('grammar_vocab', 'C1', 'word_bank', 'tenses', 'Blank 8 of A Decade of Strategic Transformation', 'should', 'The modal perfect "should clearly have consulted" expresses retrospective criticism of an action that did not happen, a hallmark C1 structure for hypothetical regret.', (SELECT id FROM wb_passage_14), 8);
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag, word_bank)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, correct_answer, explanation, passage_id, ordinal) VALUES
  ('grammar_vocab', 'C2', 'word_bank', 'collocations', 'Blank 1 of Sealing the Merger', 'landmark', '"Landmark agreement" is the fixed collocation for a highly significant, precedent-setting deal; it carries far more idiomatic weight than a generic near-miss like "important agreement".', (SELECT id FROM wb_passage_15), 1),
  ('grammar_vocab', 'C2', 'word_bank', 'collocations', 'Blank 2 of Sealing the Merger', 'discretion', '"Utmost discretion" (confidentiality) is what causes nobody outside the room to learn what was discussed; "diligence" (thoroughness/care in one''s work) doesn''t causally produce secrecy the way discretion does.', (SELECT id FROM wb_passage_15), 2),
  ('grammar_vocab', 'C2', 'word_bank', 'collocations', 'Blank 3 of Sealing the Merger', 'join', '"Join forces" is the fixed collocation meaning to combine efforts; "combine forces" is a common but less idiomatic near-miss in this exact phrase.', (SELECT id FROM wb_passage_15), 3),
  ('grammar_vocab', 'C2', 'word_bank', 'collocations', 'Blank 4 of Sealing the Merger', 'broke', '"Broke down" is the fixed phrasal collocation for negotiations collapsing mid-process, distinct from "fell through", which describes a deal failing to materialise at all.', (SELECT id FROM wb_passage_15), 4),
  ('grammar_vocab', 'C2', 'word_bank', 'collocations', 'Blank 5 of Sealing the Merger', 'gain', '"Gain traction" is the fixed collocation for building fresh momentum; "regain" would wrongly imply the talks previously had momentum before stalling.', (SELECT id FROM wb_passage_15), 5),
  ('grammar_vocab', 'C2', 'word_bank', 'collocations', 'Blank 6 of Sealing the Merger', 'balance', '"Strike a balance" is the fixed idiom for finding a satisfactory middle ground between competing interests, here shareholder value and workforce stability.', (SELECT id FROM wb_passage_15), 6),
  ('grammar_vocab', 'C2', 'word_bank', 'collocations', 'Blank 7 of Sealing the Merger', 'diligence', '"Due diligence" is the standard business/legal collocation for the careful, systematic scrutiny applied before and during a deal; "due discretion" is not the fixed professional term used in this context.', (SELECT id FROM wb_passage_15), 7),
  ('grammar_vocab', 'C2', 'word_bank', 'collocations', 'Blank 8 of Sealing the Merger', 'adversity', 'This echoes the idiom "turn adversity into opportunity", here adapted to the partnership outcome, conveying that a difficult rivalry was transformed into something mutually beneficial.', (SELECT id FROM wb_passage_15), 8);
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag, word_bank)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, correct_answer, explanation, passage_id, ordinal) VALUES
  ('grammar_vocab', 'C2', 'word_bank', 'tenses', 'Blank 1 of Containing the Fallout', 'sprang', 'The inversion "No sooner had X happened than Y..." pairs a past perfect first clause with a simple past second clause, so "sprang" is required rather than "had sprung", which would wrongly duplicate the past perfect.', (SELECT id FROM wb_passage_16), 1),
  ('grammar_vocab', 'C2', 'word_bank', 'tenses', 'Blank 2 of Containing the Fallout', 'had', '"By the time" plus a simple-past clause signals a prior completed action, which requires the past perfect auxiliary "had", not the present perfect "has" or a bare simple past.', (SELECT id FROM wb_passage_16), 2),
  ('grammar_vocab', 'C2', 'word_bank', 'tenses', 'Blank 3 of Containing the Fallout', 'would', 'The inverted third-conditional clause "Had X not insisted..." requires the modal perfect "would have + past participle" in the result clause to express an unrealised hypothetical past outcome.', (SELECT id FROM wb_passage_16), 3),
  ('grammar_vocab', 'C2', 'word_bank', 'tenses', 'Blank 4 of Containing the Fallout', 'has', '"Since the crisis broke" pairs with the present perfect "has worked" to show an action beginning in the past and continuing into the present, unlike the future "will" or simple past "was".', (SELECT id FROM wb_passage_16), 4),
  ('grammar_vocab', 'C2', 'word_bank', 'tenses', 'Blank 5 of Containing the Fallout', 'will', '"By this time next week" is a future time marker requiring the future perfect "will have compiled" for an action to be completed before that specified future point.', (SELECT id FROM wb_passage_16), 5),
  ('grammar_vocab', 'C2', 'word_bank', 'tenses', 'Blank 6 of Containing the Fallout', 'was', 'The singular subject "the general counsel" (one person, not a collective like "the department") requires the singular "was", not "were", to match the parallel past continuous "was still patching".', (SELECT id FROM wb_passage_16), 6),
  ('grammar_vocab', 'C2', 'word_bank', 'tenses', 'Blank 7 of Containing the Fallout', 'did', 'Fronting the negative-frequency adverb "rarely" triggers subject-auxiliary inversion with do-support, so "did" plus the bare infinitive "demonstrate" is required; "that single, gruelling week" anchors to one specific past event, which clashes with "would"''s habitual/repeated-pattern reading.', (SELECT id FROM wb_passage_16), 7),
  ('grammar_vocab', 'C2', 'word_bank', 'tenses', 'Blank 8 of Containing the Fallout', 'spared', 'The retrospective frame "Looking back...that the response..." states a single completed past fact, so the simple past "spared" is required rather than a perfect or continuous form.', (SELECT id FROM wb_passage_16), 8);
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag, word_bank)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, correct_answer, explanation, passage_id, ordinal) VALUES
  ('grammar_vocab', 'C2', 'word_bank', 'prepositions', 'Blank 1 of The Boardroom Standoff', 'across', '"Faced each other from across the table" is the standard collocation for two parties on opposite sides of a table; "from at the table" is ungrammatical, since "from" cannot combine with "at" this way.', (SELECT id FROM wb_passage_17), 1),
  ('grammar_vocab', 'C2', 'word_bank', 'prepositions', 'Blank 2 of The Boardroom Standoff', 'for', '"Renowned for" is the fixed prepositional pairing indicating the basis of a reputation.', (SELECT id FROM wb_passage_17), 2),
  ('grammar_vocab', 'C2', 'word_bank', 'prepositions', 'Blank 3 of The Boardroom Standoff', 'of', '"Suspicious of" is the standard prepositional collocation when the object is a person''s motives or intentions.', (SELECT id FROM wb_passage_17), 3),
  ('grammar_vocab', 'C2', 'word_bank', 'prepositions', 'Blank 4 of The Boardroom Standoff', 'at', '"Balk/baulk at" is the fixed phrasal verb for an immediate reaction of hesitation; "before anyone had even finished presenting it" rules out "balk on", which implies backing out of a prior commitment that doesn''t yet exist here.', (SELECT id FROM wb_passage_17), 4),
  ('grammar_vocab', 'C2', 'word_bank', 'prepositions', 'Blank 5 of The Boardroom Standoff', 'on', '"Hinge on" is the fixed collocation meaning to depend entirely on a single deciding factor.', (SELECT id FROM wb_passage_17), 5),
  ('grammar_vocab', 'C2', 'word_bank', 'prepositions', 'Blank 6 of The Boardroom Standoff', 'against', '"Argue against... concessions to the other side" opposes giving the other side more, consistent with "rather than capitulate"; "argue for concessions to the other side" would itself be a form of capitulating, contradicting the sentence''s own premise.', (SELECT id FROM wb_passage_17), 6),
  ('grammar_vocab', 'C2', 'word_bank', 'prepositions', 'Blank 7 of The Boardroom Standoff', 'to', '"Come to a compromise" is the fixed idiom for reaching a negotiated resolution; "after painstaking, deliberate negotiation" contradicts "came across" (an accidental discovery).', (SELECT id FROM wb_passage_17), 7),
  ('grammar_vocab', 'C2', 'word_bank', 'prepositions', 'Blank 8 of The Boardroom Standoff', 'by', '"Come about by" identifies the means or cause behind an outcome; "by sheer stamina" names the causal agent precisely, as required by this fixed pattern.', (SELECT id FROM wb_passage_17), 8);
